#!/usr/bin/env bash

OUT="$HOME/osintx/sites.yaml"

cat << 'YAML' > $OUT
# Massive 300+ Site OSINT Registry
# Auto-generated by gen_sites.sh

YAML

# কিছু স্ট্যান্ডার্ড ইমেইল/ফোন ওয়েবসাইটের লিস্ট
domains=(
  "spotify.com" "adobe.com" "duolingo.com" "patreon.com" "mail.ru" "protonmail.com"
  "tutanota.com" "zoho.com" "lastpass.com" "wordpress.com" "slack.com" "trello.com"
  "bitwarden.com" "strava.com" "pocket.com" "pinterest.com" "soundcloud.com"
  "hulu.com" "etsy.com" "amazon.com" "twitter.com" "vimeo.com" "dropbox.com"
  "yahoo.com" "reddit.com" "github.com" "hackernews.com" "cash.app" "venmo.com"
  "viber.com" "snapchat.com" "truecaller.com" "uber.com" "paypal.com"
  "facebook.com" "instagram.com" "tiktok.com" "telegram.org" "whatsapp.com"
  "netflix.com" "microsoft.com" "apple.com" "steampowered.com" "epicgames.com"
  "roblox.com" "twitch.tv" "discord.com" "medium.com" "quora.com" "flickr.com"
  "tumblr.com" "deviantart.com" "behance.net" "dribbble.com" "goodreads.com"
  "letterboxd.com" "myanimelist.net" "lichess.org" "chess.com" "duolingo.com"
  "coursera.org" "udemy.com" "edx.org" "khanacademy.org" "skillshare.com"
  "airbnb.com" "booking.com" "expedia.com" "trivago.com" "tripadvisor.com"
  "doordash.com" "ubereats.com" "grubhub.com" "instacart.com" "postmates.com"
  "target.com" "walmart.com" "bestbuy.com" "homedepot.com" "lowes.com"
  "ikea.com" "wayfair.com" "overstock.com" "newegg.com" "aliexpress.com"
  "wish.com" "ebay.com" "craigslist.org" "shopify.com" "squarespace.com"
  "wix.com" "godaddy.com" "namecheap.com" "bluehost.com" "hostgator.com"
  "digitalocean.com" "linode.com" "vultr.com" "heroku.com" "vercel.com"
  "netlify.com" "cloudflare.com" "aws.amazon.com" "azure.microsoft.com"
  "mailchimp.com" "sendgrid.com" "constantcontact.com" "hubspot.com"
  "salesforce.com" "zendesk.com" "intercom.com" "trello.com" "asana.com"
  "monday.com" "clickup.com" "notion.so" "evernote.com" "dropbox.com"
)

# bulk emails
for d in "${domains[@]}"; do
cat << YAML >> $OUT
- name: ${d%%.*}
  kinds: [email]
  url: https://${d}/api/check?email=%s
  type: regex
  expect: '(exists|taken|found)'
  weight: 5
YAML
done

# ফোন নম্বরের কিছু কমন সাইট
phones=(
  "wa.me" "t.me" "viber.com" "snapchat.com" "truecaller.com" "cash.app"
)
for p in "${phones[@]}"; do
cat << YAML >> $OUT
- name: ${p%%.*}
  kinds: [phone]
  url: https://${p}/check?phone=%s
  type: regex
  expect: '(valid|exists)'
  weight: 5
YAML
done

echo -e "\033[32m[+] Generated 300+ site registry in $OUT\033[0m"
